from gpiozero import PWMOutputDevice
import time

# Define the GPIO pins
pins = [12, 13, 18, 19, 22, 23]

# Initialize the PWM devices
devices = [PWMOutputDevice(pin) for pin in pins]

try:
    while True:
        # Cycle through the duty cycle values
        for value in range(0, 101):
            for device in devices:
                device.value = value / 100.0
            time.sleep(0.02)

        # Cycle through the duty cycle values in reverse
        for value in range(100, -1, -1):
            for device in devices:
                device.value = value / 100.0
            time.sleep(0.02)

except KeyboardInterrupt:
    print("Program interrupted")

finally:
    # Turn off all devices
    for device in devices:
        device.off()

