# PCF8574 I2C address
PCF8574_ADDRESS = 0x27

# PCF8574A I2C address
PCF8574A_ADDRESS = 0x3F

# PCF8591 I2C address
PCF8591_ADDRESS = 0x48

# PCF8591A I2C address
PCF8591A_ADDRESS = 0x70

# I2C bus
I2C_BUS = 1

class PCF8574:
    def __init__(self, address=PCF8574_ADDRESS):
        self.i2c = smbus2.SMBus(I2C_BUS)
        self.address = address

    def read(self, channel):
        try:
            return self.i2c.read_byte_data(self.address, channel)
        except Exception as e:
            print(f"Error reading from PCF8574: {e}")
            return None

    def write(self, channel, value):
        try:
            self.i2c.write_byte_data(self.address, channel, value)
        except Exception as e:
            print(f"Error writing to PCF8574: {e}")

if __name__ == "__main__":
