import time
import board
import adafruit_dht
from gpiozero import DigitalInputDevice

# Initialize the DHT sensor
dht = adafruit_dht.DHT22(board.D4)

# Initialize the GPIO pins
gpio_pins = [DigitalInputDevice(17), DigitalInputDevice(27)]

def read_sensor_data():
    try:
        # Read the temperature and humidity
        temperature = dht.temperature
        humidity = dht.humidity

        # Read the state of the GPIO pins
        gpio_states = [pin.is_active for pin in gpio_pins]

        return (temperature, humidity, gpio_states)

    except RuntimeError as error:
        # Errors happen fairly often, DHT's are hard to read, just keep going
        print(error.args[0])
        return None

    except Exception as error:
        dht.exit()
        raise error

def main():
    while True:
        data = read_sensor_data()

        if data is not None:
            temperature, humidity, gpio_states = data
            print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%,"
                  f" GPIO17: {'HIGH' if gpio_states[0] else 'LOW'},"
                  f" GPIO27: {'HIGH' if gpio_states[1] else 'LOW'}")

        time.sleep(1.0)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("Exiting...")
        dht.exit()
        for pin in gpio_pins:
            pin.close()

