import smbus2
import time
from gpiozero import I2CDevice

# VL53L0X I2C address
VL53L0X_I2C_ADDR = 0x29

# VL53L0X register addresses
VL53L0X_REG_IDENTIFICATION_MODEL_ID = 0x00
VL53L0X_REG_IDENTIFICATION_MODEL_REVISION_ID = 0x01
VL53L0X_REG_IDENTIFICATION_MODULE_TYPE = 0x06
VL53L0X_REG_IDENTIFICATION_DATE_CODE = 0x07

class VL53L0X:
    def __init__(self, address=VL53L0X_I2C_ADDR):
        self.device = I2CDevice(address)

    def read(self, register):
        with self.device as bus:
            return bus.read_byte_data(register)

    def write(self, register, value):
        with self.device as bus:
            bus.write_byte_data(register, value)

    def get_model_id(self):
        return self.read(VL53L0X_REG_IDENTIFICATION_MODEL_ID)

    def get_model_revision_id(self):
        return self.read(VL53L0X_REG_IDENTIFICATION_MODEL_REVISION_ID)

    def get_module_type(self):
        return self.read(VL53L0X_REG_IDENTIFICATION_MODULE_TYPE)

    def get_date_code(self):
        return self.read(VL53L0X_REG_IDENTIFICATION_DATE_CODE)

def main():
    sensor = VL53L0X()

    try:
        while True:
            print(f"Model ID: {sensor.get_model_id()}")
            print(f"Model Revision ID: {sensor.get_model_revision_id()}")
            print(f"Module Type: {sensor.get_module_type()}")
            print(f"Date Code: {sensor.get_date_code()}")
            time.sleep(0.1)

    except KeyboardInterrupt:
        print("Exiting...")

    except Exception as e:
        print(f"Error: {e}")
        exit(1)

    finally:
        sensor.device.close()

if __name__ == "__main__":
    main()

